// Natura PvP: an automated PvP map with three modes (Emparejamiento, Caza, Campal),
// a colossal lobby, intro cinematics, a victory cinematic and an admin panel.
// Generated by tools/natura_pvp.py.
import * as mc from "@minecraft/server";
import * as ui from "@minecraft/server-ui";
import { AREA, AREAS, BETTING, CAMPAL, campalSpawns, CORRIDOR, DUEL, DUELS, HUNT, HUNTS, insideArea, LOBBY, VICTORY } from "./gen/index.js";
import { buildArea, probe, progress, rebuildColumns, withArea } from "./builder.js";
import {
  clearPlayer, DEFAULT_KITS, describeKit, getKit, giveKit, KIT_IDS, makeItem, MENU_LORE, PLACEABLE, resetKit, saveKitFrom, scaledHuntedKit,
} from "./kits.js";

const { system, world, ItemStack } = mc;
const CFG = __CONFIG__;
const SEC = 20;
const ADMIN_TAG = "admin";

// ------------------------------------------------------------ helpers
const enumv = (E, name) => E?.[name] ?? E?.[name.toLowerCase()];
const GM = {
  adventure: enumv(mc.GameMode, "Adventure"),
  survival: enumv(mc.GameMode, "Survival"),
  spectator: enumv(mc.GameMode, "Spectator"),
  creative: enumv(mc.GameMode, "Creative"),
};
const overworld = () => world.getDimension("minecraft:overworld");
const sleep = (ticks) => new Promise((r) => system.runTimeout(r, ticks));
const valid = (e) => {
  try {
    return !!e && e.isValid !== false && (typeof e.isValid !== "function" || e.isValid());
  } catch {
    return false;
  }
};
const byId = (id) => {
  try {
    const e = world.getEntity(id);
    return valid(e) ? e : undefined;
  } catch {
    return undefined;
  }
};
const isAdmin = (p) => p.hasTag(ADMIN_TAG);
const fmtTime = (s) => `${Math.floor(s / 60)}:${String(Math.max(0, s) % 60).padStart(2, "0")}`;
const fmtMs = (ticks) => {
  const s = ticks / SEC;
  return `${Math.floor(s / 60)}:${(s % 60).toFixed(1).padStart(4, "0")}`;
};
const shuffle = (a) => {
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};
const randOf = (list) => list[Math.floor(Math.random() * list.length)];
const clone = (o) => JSON.parse(JSON.stringify(o));

function cmd(text) {
  try {
    return overworld().runCommand(text);
  } catch {
    return undefined;
  }
}

function pcmd(player, text) {
  try {
    return player.runCommand(text);
  } catch {
    return undefined;
  }
}

function title(player, main, sub = "", stay = 30) {
  try {
    player.onScreenDisplay.setTitle(main, { subtitle: sub, fadeInDuration: 2, stayDuration: stay, fadeOutDuration: 8 });
  } catch {}
}

function bar(player, text) {
  try {
    player.onScreenDisplay.setActionBar(text);
  } catch {}
}

function sound(player, id, volume = 1, pitch = 1) {
  try {
    player.playSound(id, { volume, pitch });
  } catch {}
}

function effect(player, id, seconds, amp = 0) {
  try {
    player.addEffect(id, Math.max(1, Math.round(seconds * SEC)), { amplifier: amp, showParticles: false });
  } catch {}
}

function clearEffects(player) {
  try {
    for (const e of player.getEffects()) player.removeEffect(e.typeId);
  } catch {}
}

function heal(player) {
  clearEffects(player);
  try {
    player.getComponent("minecraft:health")?.resetToMaxValue();
  } catch {}
  try {
    player.extinguishFire(false);
  } catch {}
  effect(player, "saturation", 1, 20);
}

function setMode(player, gm) {
  try {
    if (player.getGameMode() !== gm) player.setGameMode(gm);
  } catch {}
}

function tp(player, loc, facing) {
  try {
    player.teleport({ x: loc.x, y: loc.y, z: loc.z }, { dimension: overworld(), facingLocation: facing ?? loc.facing, keepVelocity: false });
  } catch {}
}

const dist2 = (a, b) => (a.x - b.x) ** 2 + (a.z - b.z) ** 2;

async function showForm(player, form) {
  for (let i = 0; i < 40; i++) {
    let r;
    try {
      r = await form.show(player);
    } catch {
      return undefined;
    }
    if (r.canceled && String(r.cancelationReason) === "UserBusy") {
      await sleep(5);
      continue;
    }
    return r;
  }
  return undefined;
}

// ------------------------------------------------------------ cinematics
// The camera flies over the arena before every match (except Campal).
function camSet(p, pos, facing, ease) {
  try {
    const opts = { location: pos, facingLocation: facing };
    if (ease) opts.easeOptions = { easeTime: ease, easeType: enumv(mc.EasingType, "InOutSine") };
    p.camera.setCamera("minecraft:free", opts);
    return;
  } catch {}
  const f = (v) => v.toFixed(2);
  pcmd(p, `camera @s set minecraft:free ${ease ? `ease ${ease} in_out_sine ` : ""}pos ${f(pos.x)} ${f(pos.y)} ${f(pos.z)} facing ${f(facing.x)} ${f(facing.y)} ${f(facing.z)}`);
}

function camFade(p, inT, hold, outT) {
  try {
    p.camera.fade({ fadeTime: { fadeInTime: inT, holdTime: hold, fadeOutTime: outT }, fadeColor: { red: 0, green: 0, blue: 0 } });
  } catch {
    pcmd(p, `camera @s fade time ${inT} ${hold} ${outT} color 0 0 0`);
  }
}

function camClear(p) {
  try {
    p.camera.clear();
  } catch {
    pcmd(p, "camera @s clear");
  }
}

function hud(p, show) {
  try {
    p.onScreenDisplay.setHudVisibility(enumv(mc.HudVisibility, show ? "Reset" : "Hide"));
  } catch {
    pcmd(p, `hud @s ${show ? "reset" : "hide"} all`);
  }
}

// No moving, jumping, crouching or turning the camera (cinematics).
const LOCKED = ["Movement", "Camera", "Jump", "Sneak", "LateralMovement", "Mount", "Dismount"];
function lockInput(p, on) {
  let done = false;
  try {
    const C = mc.InputPermissionCategory;
    for (const k of LOCKED) {
      if (C?.[k] === undefined) continue;
      p.inputPermissions.setPermissionCategory(C[k], !on);
      done = true;
    }
  } catch {}
  if (!done) for (const k of ["movement", "camera"]) pcmd(p, `inputpermission set @s ${k} ${on ? "disabled" : "enabled"}`);
}

// The epic view when a player joins: the camera stays still on a beautiful
// angle of the lobby until the player moves one block.
const EPIC = { pos: { x: -58, y: 146, z: 46 }, look: { x: 0, y: 128, z: 0 } };
function epicView(player) {
  const s = st(player);
  camFade(player, 0.1, 0.4, 1.2);
  system.runTimeout(() => {
    if (!valid(player) || st(player).mode !== "lobby") return;
    camSet(player, EPIC.pos, EPIC.look, 0);
    s.intro = { x: player.location.x, z: player.location.z };
    bar(player, "§fMuévete §eun bloque hacia delante§f para entrar al lobby");
  }, 4);
}

function epicTick(player, s) {
  const l = player.location;
  if (dist2(l, s.intro) >= 1) {
    s.intro = null;
    camFade(player, 0.3, 0.3, 0.8);
    system.runTimeout(() => {
      if (valid(player)) camClear(player);
    }, 7);
    return;
  }
  if (tick % 4 === 0) bar(player, "§fMuévete §eun bloque hacia delante§f para entrar al lobby");
}

// shots: [{ pos, look, ease (s), hold (s), title, sub }] for every player (a function of the player)
async function cinematic(players, shotsOf) {
  const list = players.filter(valid);
  for (const p of list) {
    hud(p, false);
    camFade(p, 0.3, 0.3, 0.6);
  }
  await sleep(6);
  const plans = new Map(list.map((p) => [p.id, shotsOf(p)]));
  const steps = Math.max(...[...plans.values()].map((s) => s.length));
  for (let i = 0; i < steps; i++) {
    let wait = 0;
    for (const p of list) {
      const s = plans.get(p.id)[i];
      if (!s || !valid(p)) continue;
      camSet(p, s.pos, s.look, i === 0 ? 0 : s.ease);
      if (s.title) title(p, s.title, s.sub ?? "", Math.round(((s.ease ?? 0) + (s.hold ?? 0)) * SEC));
      wait = Math.max(wait, (i === 0 ? 0 : s.ease ?? 0) + (s.hold ?? 0));
    }
    await sleep(Math.max(1, Math.round(wait * SEC)));
  }
  for (const p of list) {
    if (!valid(p)) continue;
    camFade(p, 0.25, 0.2, 0.5);
  }
  await sleep(6);
  for (const p of list) {
    if (!valid(p)) continue;
    camClear(p);
    hud(p, true);
  }
}

// ------------------------------------------------------------ settings
const DEFAULTS = {
  duel: { enabled: true, countdown: 5, maxTime: 0, cinematic: true, maps: DUELS.map(() => true), nextMap: -1 },
  hunt: {
    enabled: true, maxPlayers: 6, minPlayers: 2, maxDuo: 7, minDuo: 4, lobbyCountdown: 30, headStart: 20, timeLimit: 300, reveal: 60, music: true,
    friendlyFire: false, lastStandMinutes: 3, cinematic: true, chests: true, maps: HUNTS.map(() => true), nextMap: -1,
  },
  campal: { enabled: true, reward: true, spawnProtection: 3, combatTag: 8, sidebar: true },
  world: { time: 2, lockTime: true, naturalRegen: true },
};
// saved settings of an older version: these ones take the new defaults
const SETTINGS_VERSION = 2;
const RESET_OLD = { hunt: ["timeLimit", "maxPlayers"] };
let S = clone(DEFAULTS);

function loadSettings() {
  S = clone(DEFAULTS);
  try {
    const saved = JSON.parse(world.getDynamicProperty("natura:settings") ?? "{}");
    const old = saved._v !== SETTINGS_VERSION;
    for (const k of Object.keys(DEFAULTS)) {
      for (const [key, v] of Object.entries(saved[k] ?? {})) {
        if (!(key in S[k]) || typeof v !== typeof S[k][key]) continue;
        if (old && RESET_OLD[k]?.includes(key)) continue;
        if (Array.isArray(S[k][key])) S[k][key] = S[k][key].map((d, i) => (typeof v[i] === "boolean" ? v[i] : d));
        else S[k][key] = v;
      }
    }
  } catch {}
}

function saveSettings() {
  world.setDynamicProperty("natura:settings", JSON.stringify({ ...S, _v: SETTINGS_VERSION }));
}

const TIMES = [["Amanecer", 23000], ["Mañana", 1000], ["Mediodía", 6000], ["Atardecer", 12000], ["Noche", 14000], ["Medianoche", 18000]];

function applyWorld() {
  const w = S.world;
  cmd(`gamerule dodaylightcycle ${!w.lockTime}`);
  cmd(`time set ${TIMES[w.time]?.[1] ?? 6000}`);
  // no weather: always clear
  cmd("gamerule doweathercycle false");
  cmd("weather clear");
  cmd(`gamerule naturalregeneration ${w.naturalRegen}`);
}

function applyGamerules() {
  for (const rule of [
    "keepinventory true", "doimmediaterespawn true", "domobspawning false", "dofiretick false", "mobgriefing false",
    "tntexplodes false", "doinsomnia false", "commandblockoutput false", "showcoordinates false", "spawnradius 0",
    "pvp true", "falldamage true", "showdeathmessages true", "doentitydrops true", "dotiledrops false",
    "projectilescanbreakblocks false", "dopatrolspawning false", "dotraderspawning false",
    "sendcommandfeedback false", "commandblocksenabled true", "showtags false",
  ]) cmd(`gamerule ${rule}`);
  cmd("difficulty normal");
  try {
    world.setDefaultSpawnLocation({ x: Math.floor(LOBBY.spawn.x), y: LOBBY.spawn.y, z: Math.floor(LOBBY.spawn.z) });
  } catch {}
  applyWorld();
}

// ------------------------------------------------------------ stats
let STATS = {};
let statsDirty = false;
const STAT_NAMES = { k: "Bajas", d: "Muertes", dw: "Duelos ganados", dl: "Duelos perdidos", hw: "Cazas ganadas", hl: "Cazas perdidas", ck: "Bajas en campal" };

function loadStats() {
  try {
    STATS = JSON.parse(world.getDynamicProperty("natura:stats") ?? "{}");
  } catch {
    STATS = {};
  }
}

function addStat(player, key, n = 1) {
  const name = typeof player === "string" ? player : player.name;
  const s = (STATS[name] ??= {});
  s[key] = (s[key] ?? 0) + n;
  statsDirty = true;
}

function top(key, n = 3) {
  return Object.entries(STATS).filter(([, s]) => s[key] > 0).sort((a, b) => b[1][key] - a[1][key]).slice(0, n);
}


system.runInterval(() => {
  if (!statsDirty) return;
  statsDirty = false;
  let json = JSON.stringify(STATS);
  // keep the property small: forget the players with fewer games
  while (json.length > 30000) {
    const names = Object.keys(STATS).sort((a, b) => sum(STATS[a]) - sum(STATS[b]));
    for (const n of names.slice(0, Math.ceil(names.length / 10))) delete STATS[n];
    json = JSON.stringify(STATS);
  }
  world.setDynamicProperty("natura:stats", json);
}, 100);

function sum(s) {
  return Object.entries(s).reduce((a, [k, v]) => a + (k === "pk" ? 1 : v), 0);
}

// ------------------------------------------------------------ player state
// mode: lobby | duel | hunt | hunt_spec | campal | free
const P = new Map();

function st(player) {
  let s = P.get(player.id);
  if (!s) {
    s = { mode: "lobby", hurtTick: -9999, attacker: undefined, attackerTick: -9999, pad: null, pk: null };
    P.set(player.id, s);
  }
  return s;
}

const built = (id) => world.getDynamicProperty(`natura:built:${id}`) === CFG.buildVersion;

function menuItem(id, name, lore) {
  const item = new ItemStack(id, 1);
  item.nameTag = name;
  try {
    item.setLore([...lore, MENU_LORE]);
  } catch {}
  try {
    item.lockMode = enumv(mc.ItemLockMode, "slot");
  } catch {}
  try {
    item.keepOnDeath = true;
  } catch {}
  return item;
}

const ITEMS = {
  selector: () => menuItem("minecraft:compass", "§a§lMenú de Natura PvP", ["§7Modos, espectar y estadísticas"]),
  admin: () => menuItem("minecraft:clock", "§c§lPanel de administración", ["§7Solo para administradores"]),
  leave: () => menuItem("minecraft:recovery_compass", "§c§lVolver al lobby", ["§7Sal del campal"]),
};

function itemKind(item) {
  if (!item) return undefined;
  let lore = [];
  try {
    lore = item.getLore();
  } catch {}
  if (!lore.includes(MENU_LORE)) return undefined;
  if (item.typeId === "minecraft:compass") return "selector";
  if (item.typeId === "minecraft:clock") return "admin";
  if (item.typeId === "minecraft:recovery_compass") return "leave";
  return undefined;
}

function lobbyItems(player) {
  const inv = player.getComponent("minecraft:inventory")?.container;
  if (!inv) return;
  inv.setItem(0, ITEMS.selector());
  inv.setItem(8, isAdmin(player) ? ITEMS.admin() : undefined);
}

// ------------------------------------------------------------ music
// One song per situation: the lobby (always, in a loop), the hunt (the whole
// hunt, the final duel too) and the victory of the hunted player.
const TRACKS = CFG.tracks; // [{ id, name, ticks, use, volume }]
const trackOf = (use) => TRACKS.findIndex((t) => t.use === use);
const LOBBY_SONG = trackOf("lobby"), HUNT_SONG = trackOf("hunt"), WIN_SONG = trackOf("win");

const playing = new Map(); // player id -> sound id playing now
const pendingPlay = new Map(); // player id -> token of the song about to start
const personal = new Map(); // player id -> { queue, i, end }
let huntMusic = null; // { queue, i, end }

// The song starts a few ticks after the previous one is stopped: a "stopsound"
// and a "playsound" of the same song in the same tick left the player in silence.
function playTrack(player, index) {
  stopSong(player);
  const t = TRACKS[index];
  if (!t) return;
  const volume = songVolume(player, t);
  if (volume <= 0) return; // the player turned this song off
  const token = {};
  pendingPlay.set(player.id, token);
  playing.set(player.id, t.id);
  system.runTimeout(() => {
    if (pendingPlay.get(player.id) !== token || !valid(player)) return;
    pendingPlay.delete(player.id);
    try {
      player.playSound(t.id, { volume });
    } catch {}
  }, 4);
}

function stopSong(player) {
  pendingPlay.delete(player.id);
  const id = playing.get(player.id);
  if (!id) return;
  pcmd(player, `stopsound @s ${id}`);
  playing.delete(player.id);
}

function playPersonal(player, queue) {
  personal.delete(player.id);
  stopSong(player);
  if (!queue.length || queue.some((i) => !TRACKS[i])) return;
  personal.set(player.id, { queue, i: 0, end: system.currentTick + TRACKS[queue[0]].ticks });
  playTrack(player, queue[0]);
}

function stopMusic(player) {
  personal.delete(player.id);
  stopSong(player);
}

// ------------------------------------------------------------ the options of every player
// Each player can turn every song off or change its volume, and turn off the
// epic view when joining. Kept in the player (dynamic property).
const USE_NAME = { lobby: "lobby", hunt: "caza", win: "victoria" };
function opts(player) {
  const s = st(player);
  if (!s.opts) {
    s.opts = { vol: {}, epic: true };
    try {
      const o = JSON.parse(player.getDynamicProperty("natura:opts") ?? "{}");
      if (o && typeof o.vol === "object") s.opts.vol = o.vol;
      if (typeof o.epic === "boolean") s.opts.epic = o.epic;
    } catch {}
  }
  return s.opts;
}

function saveOpts(player) {
  try {
    player.setDynamicProperty("natura:opts", JSON.stringify(opts(player)));
  } catch {}
}

// the volume of a song for a player (0 = off), from 0 to 1
function songVolume(player, t) {
  const v = opts(player).vol[t.use];
  return typeof v === "number" ? Math.max(0, Math.min(100, v)) / 100 : t.volume ?? 1;
}

async function openOptions(player) {
  const o = opts(player);
  const list = TRACKS.map((t, i) => [t, i]).filter(([t]) => USE_NAME[t.use]);
  const form = new ui.ModalFormData().title("§l§3OPCIONES");
  for (const [t] of list) {
    const v = Math.round(songVolume(player, t) * 100);
    form.toggle(`§f${t.name} §7(${USE_NAME[t.use]})`, { defaultValue: v > 0 });
    form.slider("§7  volumen", 5, 100, { valueStep: 5, defaultValue: Math.max(5, v || Math.round((t.volume ?? 1) * 100)) });
  }
  form.toggle("§fVista épica al entrar al mundo", { defaultValue: o.epic });
  form.submitButton("§a§lGuardar");
  const r = await showForm(player, form);
  if (!r || r.canceled || !r.formValues) return;
  const v = r.formValues;
  list.forEach(([t], k) => {
    o.vol[t.use] = v[k * 2] ? v[k * 2 + 1] : 0;
  });
  o.epic = !!v[list.length * 2];
  saveOpts(player);
  player.sendMessage(`§3[Opciones]§r Guardado: ${list.map(([t]) => `§f${t.name} §7${o.vol[t.use] ? `${o.vol[t.use]}%` : "§cno"}`).join("§7, ")}§7, vista épica ${o.epic ? "§así" : "§cno"}§7.`);
  // the new volume right away
  const mode = st(player).mode;
  if (mode === "lobby") lobbyMusic(player);
  else if ((mode === "hunt" || mode === "hunt_spec") && hunt.phase === "running") huntMusicJoin(player);
}

// the lobby song, always, in a loop
function lobbyMusic(player) {
  if (LOBBY_SONG >= 0) playPersonal(player, [LOBBY_SONG]);
  else stopMusic(player);
}

// Emparejamiento and Campal have no music
function modeMusic(player) {
  stopMusic(player);
}

function huntMusicStart(queue) {
  huntMusic = queue.length ? { queue, i: 0, end: system.currentTick + TRACKS[queue[0]].ticks } : null;
  for (const p of huntParticipants()) {
    personal.delete(p.id);
    if (huntMusic) playTrack(p, queue[0]);
    else stopSong(p);
  }
}

function huntMusicJoin(player) {
  personal.delete(player.id);
  if (huntMusic) playTrack(player, huntMusic.queue[huntMusic.i]);
  else stopSong(player);
}

function huntMusicStop() {
  huntMusic = null;
  for (const p of huntParticipants()) stopSong(p);
}

// the songs loop: when one ends it starts again
system.runInterval(() => {
  const now = system.currentTick;
  for (const [id, m] of personal) {
    const p = byId(id);
    if (!p) {
      personal.delete(id);
      playing.delete(id);
      continue;
    }
    if (now < m.end) continue;
    m.i = (m.i + 1) % m.queue.length;
    m.end = now + TRACKS[m.queue[m.i]].ticks;
    playTrack(p, m.queue[m.i]);
  }
  if (huntMusic && now >= huntMusic.end) {
    huntMusic.i = (huntMusic.i + 1) % huntMusic.queue.length;
    huntMusic.end = now + TRACKS[huntMusic.queue[huntMusic.i]].ticks;
    for (const p of huntParticipants()) playTrack(p, huntMusic.queue[huntMusic.i]);
  }
}, 5);

system.runInterval(() => cmd("weather clear"), 60 * SEC);

// ------------------------------------------------------------ lobby
// quiet: the song starts once the player really is in the world (see joinMusic)
function sendToLobby(player, message, quiet = false) {
  const s = st(player);
  s.mode = "lobby";
  s.role = undefined;
  s.pad = "spawn";
  s.intro = null;
  if (s.fog) secretFogOff(player);
  lockInput(player, false);
  camClear(player);
  hud(player, true);
  s.joinMusic = null;
  if (quiet) stopMusic(player);
  else lobbyMusic(player);
  setMode(player, GM.adventure);
  clearPlayer(player);
  heal(player);
  effect(player, "resistance", 10, 255);
  tp(player, LOBBY.spawn, LOBBY.look);
  try {
    player.setSpawnPoint({ dimension: overworld(), x: Math.floor(LOBBY.spawn.x), y: LOBBY.spawn.y, z: Math.floor(LOBBY.spawn.z) });
  } catch {}
  lobbyItems(player);
  if (message) player.sendMessage(message);
}

function leaveQueues(player) {
  const a = duel.queue.indexOf(player.id);
  if (a >= 0) duel.queue.splice(a, 1);
  for (const k of KINDS) {
    const b = hunt.queues[k].indexOf(player.id);
    if (b >= 0) hunt.queues[k].splice(b, 1);
  }
}

function inCombat(player) {
  const s = st(player);
  return system.currentTick - s.hurtTick < S.campal.combatTag * SEC;
}

function lockEffects(p, seconds) {
  effect(p, "slowness", seconds, 255);
  effect(p, "weakness", seconds, 255);
  effect(p, "resistance", seconds, 255);
}

function unlock(p) {
  for (const e of ["slowness", "weakness", "resistance", "blindness"]) {
    try {
      p.removeEffect(e);
    } catch {}
  }
}

// ------------------------------------------------------------ spectating
// Anyone in the lobby can watch a duel, the hunt or the Campal (spectator mode).
// Crouch: next player. Keep crouching 2 s: back to the lobby.
function specTargets() {
  const out = [];
  duel.matches.forEach((m, i) => {
    if (m && m.phase !== "end") out.push({ kind: "duel", i, label: `§b§l${m.names[0]} vs ${m.names[1]}`, sub: `Emparejamiento · ${DUELS[i].name}` });
  });
  if (hunt.phase === "running") out.push({ kind: "hunt", label: `§c§lCAZA: ${preyNames()}`, sub: `${KIND[hunt.kind].name} · ${huntMap().name} · ${hunt.alive.size} vivos` });
  const cp = campalPlayers();
  if (cp.length) out.push({ kind: "campal", label: "§a§lCAMPAL", sub: `${cp.length} jugando` });
  return out;
}

function specPlayers(t) {
  if (t.kind === "duel") return duel.matches[t.i] ? duelPlayers(duel.matches[t.i]).filter(Boolean) : [];
  if (t.kind === "hunt") return [...alivePreys(), ...aliveHunters()].map(byId).filter(Boolean);
  return campalPlayers();
}

function specActive(t) {
  if (t.kind === "duel") return !!duel.matches[t.i] && duel.matches[t.i].phase !== "end";
  if (t.kind === "hunt") return hunt.phase === "running";
  return S.campal.enabled;
}

function specArea(t) {
  return t.kind === "duel" ? DUELS[t.i].id : t.kind === "hunt" ? huntMap().id : "campal";
}

function specView(player, t) {
  const list = specPlayers(t);
  if (!list.length) {
    const a = AREA[specArea(t)];
    return tp(player, { x: (a.x0 + a.x1) / 2, y: (t.kind === "duel" ? DUEL.y : CAMPAL.y) + 25, z: (a.z0 + a.z1) / 2 });
  }
  const target = list[(t.k ?? 0) % list.length];
  let dir = { x: 0, z: 1 };
  try {
    const v = target.getViewDirection();
    const n = Math.hypot(v.x, v.z) || 1;
    dir = { x: v.x / n, z: v.z / n };
  } catch {}
  const l = target.location;
  tp(player, { x: l.x - dir.x * 4, y: l.y + 2.5, z: l.z - dir.z * 4 }, { x: l.x, y: l.y + 1.4, z: l.z });
  if (t.kind !== "hunt") bar(player, `§7Mirando a §f${target.name}`);
}

function specEnter(player, t) {
  if (st(player).mode !== "lobby") return;
  if (!specActive(t)) return player.sendMessage("§7Esa partida ya terminó.");
  if (t.kind === "hunt") return huntSpectate(player);
  leaveQueues(player);
  stopMusic(player);
  const s = st(player);
  s.mode = "spec";
  s.spec = { ...t, k: 0 };
  s.sneak = 0;
  clearPlayer(player);
  setMode(player, GM.spectator);
  specView(player, s.spec);
  title(player, "§7§lESPECTADOR", "§fagáchate: siguiente jugador · mantén 2 s: salir", 50);
  player.sendMessage("§7[Espectador]§r Agáchate para pasar al siguiente jugador; mantén agachado 2 s (o usa §e/natura:lobby§r) para volver al lobby.");
}

async function specMenu(player) {
  const list = specTargets();
  if (!list.length) return player.sendMessage("§7[Espectador] Ahora mismo no hay ninguna partida.");
  await menu(player, "§l§7ESPECTAR", "§7Elige qué partida quieres ver.\n ", list.map((t) => [`${t.label}\n§r§8${t.sub}`, () => specEnter(player, t),
    t.kind === "duel" ? "textures/items/diamond_sword" : t.kind === "hunt" ? "textures/items/bow_standby" : "textures/items/iron_sword"]), () => openSelector(player));
}

// called every 5 ticks for players in "spec" or "hunt_spec"
function specTick(player, s) {
  const t = s.mode === "hunt_spec" ? (s.spec ??= { kind: "hunt", k: 0 }) : s.spec;
  if (!t) return sendToLobby(player);
  if (s.mode === "spec" && !specActive(t)) return sendToLobby(player, "§7[Espectador] La partida que mirabas terminó.");
  if (player.isSneaking) s.sneak = (s.sneak ?? 0) + 5;
  else {
    if (s.sneak > 0 && s.sneak < 30) {
      t.k = (t.k ?? 0) + 1;
      specView(player, t);
    }
    s.sneak = 0;
  }
  if (s.sneak >= 40) {
    hunt.spectators.delete(player.id);
    return sendToLobby(player, "§7Volviste al lobby.");
  }
  const l = player.location;
  const top = t.kind === "duel" ? DUEL.wallTop : t.kind === "hunt" ? HUNT.clearTop + 60 : CAMPAL.wallTop;
  if (!insideArea(specArea(t), l.x, l.z, -2) || l.y > top || l.y < HUNT.floor) specView(player, t);
  if (s.mode === "spec" && tick % 8 === 0) bar(player, "§7ESPECTADOR §8| §fagáchate: siguiente §8| §fmantén 2 s: salir");
}

// ------------------------------------------------------------ Emparejamiento (1v1)
const duel = { queue: [], matches: [] }; // matches[i] = match on map i

function freeDuelMaps() {
  return DUELS.map((_, i) => i).filter((i) => S.duel.maps[i] !== false && !duel.matches[i] && built(DUELS[i].id));
}

function duelJoin(player) {
  if (!S.duel.enabled) return player.sendMessage("§c[Emparejamiento] El modo está desactivado por un administrador.");
  if (!DUELS.some((d) => built(d.id))) return player.sendMessage("§e[Emparejamiento] Las arenas se están construyendo, espera un momento.");
  if (st(player).mode !== "lobby") return;
  if (duel.queue.includes(player.id)) return player.sendMessage("§e[Emparejamiento] Ya estás en la cola.");
  leaveQueues(player);
  duel.queue.push(player.id);
  sound(player, "random.orb", 0.7, 1.2);
  player.sendMessage(`§b[Emparejamiento]§r Entraste a la cola §7(${duel.queue.length} en cola)§r. Buscando rival...`);
}

function duelLeave(player) {
  const i = duel.queue.indexOf(player.id);
  if (i < 0) return;
  duel.queue.splice(i, 1);
  player.sendMessage("§b[Emparejamiento]§r Saliste de la cola.");
}

// The intro of a hunt, for one player: their zone from the air, then them.
function huntShots(map, p, isPrey, hunters, preyName, mate) {
  const l = p.location;
  const eye = { x: l.x, y: l.y + 1.6, z: l.z };
  return [
    { pos: { x: l.x + 34, y: l.y + 40, z: l.z + 34 }, look: eye, hold: 0 },
    { pos: { x: l.x - 30, y: l.y + 22, z: l.z + 26 }, look: eye, ease: 3.2, hold: 0.2, title: `§6§l${map.name.toUpperCase()}`, sub: `§fCaza · ${map.desc}` },
    { pos: { x: l.x + 3, y: l.y + 2.2, z: l.z + 3 }, look: eye, ease: 2, hold: 0.8, title: isPrey ? "§c§lERES EL CAZADO" : "§a§lERES CAZADOR", sub: isPrey ? `§f${hunters} cazador(es) te buscan${mate ? ` · con §c${mate}` : ""}` : `§fatrapa a §c${preyName}` },
  ];
}

function duelShots(map, spawns, names) {
  const c = { x: map.cx + 0.5, y: DUEL.y + 3, z: map.cz + 0.5 };
  const face = (sp, other) => {
    const dx = other.x - sp.x, dz = other.z - sp.z, d = Math.hypot(dx, dz);
    return { pos: { x: sp.x + (dx / d) * 3.6, y: sp.y + 1.9, z: sp.z + (dz / d) * 3.6 }, look: { x: sp.x, y: sp.y + 1.6, z: sp.z } };
  };
  const a = face(spawns[0], spawns[1]), b = face(spawns[1], spawns[0]);
  return () => [
    { pos: { x: c.x - 27, y: c.y + 52, z: c.z - 27 }, look: c, hold: 0 },
    { pos: { x: c.x + 26, y: c.y + 22, z: c.z - 24 }, look: c, ease: 3, hold: 0.2, title: `§b§l${map.name.toUpperCase()}`, sub: "§fEmparejamiento · 1 contra 1" },
    { ...a, ease: 1.8, hold: 0.4, title: `§e§l${names[0]}`, sub: "§7kit de diamante encantado" },
    { ...b, ease: 1.8, hold: 0.6, title: `§fVS §e§l${names[1]}`, sub: "§7¡que gane el mejor!" },
  ];
}

function startDuel(i, a, b) {
  const map = DUELS[i];
  const spawns = map.spawns();
  const m = { i, ids: [a.id, b.id], names: [a.name, b.name], spawns, phase: "intro", t: S.duel.countdown, time: 0 };
  duel.matches[i] = m;
  [a, b].forEach((p, k) => {
    const s = st(p);
    s.mode = "duel";
    s.match = m;
    s.pad = null;
    setMode(p, GM.adventure);
    heal(p);
    tp(p, spawns[k]);
    giveKit(p, getKit("duel"));
    lockEffects(p, 60);
    modeMusic(p);
    p.sendMessage(`§b[Emparejamiento]§r Rival: §e${k ? a.name : b.name}§r · mapa: §b${map.name}§r.`);
  });
  const go = () => {
    if (m.phase !== "intro") return;
    m.phase = "countdown";
  };
  if (S.duel.cinematic) cinematic([a, b], duelShots(map, spawns, m.names)).then(go);
  else go();
}

function duelPlayers(m) {
  return m.ids.map(byId);
}

function endDuel(m, winnerIdx, reason) {
  if (m.phase === "end") return;
  m.phase = "end";
  const players = duelPlayers(m);
  if (winnerIdx === undefined) {
    for (const p of players) if (p) title(p, "§e§lEMPATE", reason ?? "");
    world.sendMessage(`§b[Emparejamiento]§r §e${m.names[0]}§r y §e${m.names[1]}§r empataron.`);
  } else {
    const w = players[winnerIdx], l = players[1 - winnerIdx];
    addStat(m.names[winnerIdx], "dw");
    addStat(m.names[1 - winnerIdx], "dl");
    if (w) {
      title(w, "§a§l¡VICTORIA!", `§fderrotaste a §e${m.names[1 - winnerIdx]}`);
      sound(w, "random.levelup");
      unlock(w);
      effect(w, "resistance", 5, 255);
    }
    if (l) title(l, "§c§lDERROTA", `§fte ganó §e${m.names[winnerIdx]}`);
    world.sendMessage(`§b[Emparejamiento]§r §a${m.names[winnerIdx]}§r ganó a §c${m.names[1 - winnerIdx]}§r en §b${DUELS[m.i].name}§r${reason ? ` §7(${reason})` : ""}.`);
  }
  for (const id of m.ids) {
    const s = P.get(id);
    if (s?.match === m) s.match = undefined;
  }
  system.runTimeout(() => {
    for (const p of duelPlayers(m)) if (p && st(p).mode === "duel") sendToLobby(p);
    if (duel.matches[m.i] === m) duel.matches[m.i] = undefined;
  }, 3 * SEC);
}

function duelTick() {
  // matchmaking
  duel.queue = duel.queue.filter((id) => byId(id) && st(byId(id)).mode === "lobby");
  if (S.duel.enabled) {
    while (duel.queue.length >= 2) {
      const free = freeDuelMaps();
      if (!free.length) break;
      const i = free.includes(S.duel.nextMap) ? S.duel.nextMap : randOf(free);
      const a = byId(duel.queue.shift()), b = byId(duel.queue.shift());
      startDuel(i, a, b);
    }
  }
  for (const m of duel.matches) {
    if (!m || m.phase === "end" || m.phase === "intro") continue;
    const players = duelPlayers(m);
    if (m.phase === "countdown") {
      if (m.t > 0) {
        for (const p of players) {
          if (!p) continue;
          const c = m.t <= 2 ? "§c" : m.t <= 3 ? "§6" : "§e";
          title(p, `${c}§l${m.t}`, "§7prepárate", 16);
          sound(p, "note.pling", 0.8, m.t <= 3 ? 1.5 : 1);
        }
        m.t--;
      } else {
        m.phase = "fight";
        for (const p of players) {
          if (!p) continue;
          unlock(p);
          title(p, "§a§l¡A PELEAR!", "", 20);
          sound(p, "mob.enderdragon.growl", 0.4, 1.3);
        }
      }
    } else if (m.phase === "fight") {
      m.time++;
      const left = S.duel.maxTime > 0 ? S.duel.maxTime - m.time : undefined;
      if (left !== undefined && left <= 0) endDuel(m, undefined, "se acabó el tiempo");
    }
  }
}

// ------------------------------------------------------------ Caza (hunt)
// Two kinds of hunt: "solo" (1 hunted against everybody) and "duo" (2 hunted
// against everybody). Each kind has its own queue; one hunt runs at a time.
const KINDS = ["solo", "duo"];
const KIND = {
  solo: { name: "1 contra todos", short: "1 vs todos", preys: 1 },
  duo: { name: "2 contra todos", short: "2 vs todos", preys: 2 },
};
const huntMin = (kind) => (kind === "duo" ? Math.max(4, S.hunt.minDuo) : Math.max(2, S.hunt.minPlayers));
const huntMax = (kind) => (kind === "duo" ? S.hunt.maxDuo : S.hunt.maxPlayers);
const hunt = {
  phase: "idle", kind: "solo", queues: { solo: [], duo: [] }, cd: { solo: null, duo: null }, map: 0, preys: [], hunters: [], alive: new Set(),
  spectators: new Set(), names: {}, timeLeft: 0, headLeft: 0, released: 0, finalDuel: false, lastStand: false, placed: new Set(), nextHunted: undefined,
};
const huntMap = () => HUNTS[hunt.map];
const isPrey = (id) => hunt.preys.includes(id);
const alivePreys = () => hunt.preys.filter((id) => hunt.alive.has(id));
const preyNames = (ids = hunt.preys) => ids.map((id) => hunt.names[id]).join(" y ");
const queueOf = (id) => KINDS.find((k) => hunt.queues[k].includes(id));

function huntJoin(player, kind = "solo") {
  if (!S.hunt.enabled) return player.sendMessage("§c[Caza] El modo está desactivado por un administrador.");
  if (!HUNTS.some((m) => built(m.id))) return player.sendMessage("§e[Caza] Los mapas de caza se están construyendo, espera un momento.");
  if (st(player).mode !== "lobby") return;
  const q = hunt.queues[kind];
  if (q.includes(player.id)) return player.sendMessage(`§e[Caza] Ya estás en la cola de §f${KIND[kind].name}§e.`);
  if (hunt.phase === "running" || hunt.phase === "ending") return player.sendMessage("§e[Caza] Hay una caza en curso. Entra a la cola cuando acabe, o mírala como espectador desde el menú.");
  const max = huntMax(kind);
  if (q.length >= max) return player.sendMessage(`§c[Caza] La caza ${KIND[kind].name} está llena (${max}/${max}).`);
  leaveQueues(player);
  q.push(player.id);
  sound(player, "random.orb", 0.7, 0.9);
  for (const id of q) byId(id)?.sendMessage(`§c[Caza · ${KIND[kind].name}]§r §e${player.name}§r entró a la caza §7(${q.length}/${max})`);
}

function huntLeave(player) {
  const kind = queueOf(player.id);
  if (!kind) return;
  hunt.queues[kind].splice(hunt.queues[kind].indexOf(player.id), 1);
  player.sendMessage("§c[Caza]§r Saliste de la cola.");
}

// which hunt: 1 against everybody or 2 against everybody
async function huntChoice(player) {
  const kind = queueOf(player.id);
  if (kind) return menu(player, "§l§cCAZA", `§fEstás en la cola de §e${KIND[kind].name}§f.\n `, [
    ["§c§lSALIR DE LA COLA", () => huntLeave(player), "textures/ui/cancel"],
  ]);
  const line = (k) => {
    const n = hunt.queues[k].length;
    return hunt.cd[k] != null ? `empieza en ${hunt.cd[k]} s · ${n}/${huntMax(k)}` : `${n}/${huntMax(k)} en cola · mínimo ${huntMin(k)}`;
  };
  await menu(player, "§l§cCAZA", "§fElige la caza. En las dos, cuando solo queda §aun cazador§f empieza el §4duelo final§f (2:30).\n ", [
    [`§c§l1 CONTRA TODOS\n§r§8${line("solo")}`, () => huntJoin(player, "solo"), "textures/items/bow_standby"],
    [`§6§l2 CONTRA TODOS\n§r§8${line("duo")}`, () => huntJoin(player, "duo"), "textures/items/crossbow_standby"],
  ], () => openSelector(player));
}

function huntSpectate(player) {
  if (hunt.phase !== "running") return player.sendMessage("§e[Caza] No hay ninguna caza en curso.");
  leaveQueues(player);
  const s = st(player);
  s.mode = "hunt_spec";
  hunt.spectators.add(player.id);
  clearPlayer(player);
  setMode(player, GM.spectator);
  const target = alivePreys().map(byId).find(Boolean);
  tp(player, target ? { x: target.location.x, y: target.location.y + 12, z: target.location.z } : huntCenter());
  s.spec = { kind: "hunt", k: 0 };
  s.sneak = 0;
  player.sendMessage("§c[Caza]§r Estás mirando la caza. Agáchate para pasar al siguiente jugador; mantén 2 s (o §e/natura:lobby§r) para volver.");
  huntMusicJoin(player);
}

function huntCenter() {
  const m = huntMap();
  const s = m.surface(m.cx, m.cz);
  return { x: m.cx + 0.5, y: s.y + 25, z: m.cz + 0.5 };
}

function randomSpot(awayFrom, minDist, m = huntMap()) {
  let best, bestD = -1;
  for (let i = 0; i < 120; i++) {
    const x = m.x0 + 14 + Math.floor(Math.random() * (HUNT.size - 28));
    const z = m.z0 + 14 + Math.floor(Math.random() * (HUNT.size - 28));
    const s = m.surface(x, z);
    if (!s.safe) continue;
    const loc = { x: x + 0.5, y: s.y, z: z + 0.5 };
    const d = awayFrom ? Math.sqrt(dist2(loc, awayFrom)) : 1e9;
    if (d >= minDist) return loc;
    if (d > bestD) {
      best = loc;
      bestD = d;
    }
  }
  return best ?? { x: m.cx + 0.5, y: m.surface(m.cx, m.cz).y + 1, z: m.cz + 0.5 };
}

function huntParticipants() {
  return [...new Set([...hunt.preys, ...hunt.hunters, ...hunt.spectators])].map(byId).filter(Boolean);
}

function aliveHunters() {
  return hunt.hunters.filter((id) => hunt.alive.has(id));
}

// Loot for the chests of the structures (both sides can take it).
const LOOT = [
  [8, () => ({ id: "minecraft:arrow", count: 8 + Math.floor(Math.random() * 9) })],
  [8, () => ({ id: "minecraft:ender_pearl", count: 2 + Math.floor(Math.random() * 3) })],
  [9, () => ({ id: "minecraft:golden_apple", count: 2 + Math.floor(Math.random() * 3) })],
  [5, () => ({ id: "minecraft:splash_potion", potion: 22, count: 1 + Math.floor(Math.random() * 2) })],
  [6, () => ({ id: "minecraft:snowball", count: 8 + Math.floor(Math.random() * 9) })],
  [5, () => ({ id: "minecraft:golden_carrot", count: 4 })],
  [3, () => ({ id: "minecraft:fishing_rod" })],
  [1, () => ({ id: "minecraft:enchanted_golden_apple" })],
  [1, () => ({ id: "minecraft:totem_of_undying" })],
];

function lootRoll() {
  const total = LOOT.reduce((a, [w]) => a + w, 0);
  let r = Math.random() * total;
  for (const [w, f] of LOOT) if ((r -= w) <= 0) return f();
  return LOOT[0][1]();
}

function fillChests(map) {
  const marks = map.chests();
  const sections = new Map();
  for (const c of marks) {
    const k = `${Math.floor(c.x / 160)},${Math.floor(c.z / 160)}`;
    if (!sections.has(k)) sections.set(k, []);
    sections.get(k).push(c);
  }
  for (const list of sections.values()) {
    const xs = list.map((c) => c.x), zs = list.map((c) => c.z);
    withArea(Math.min(...xs), Math.min(...zs), Math.max(...xs), Math.max(...zs), (dim) => {
      for (const c of list) {
        try {
          const block = dim.getBlock({ x: c.x, y: c.y, z: c.z });
          if (!block) continue;
          block.setPermutation(mc.BlockPermutation.resolve("minecraft:chest", { "minecraft:cardinal_direction": c.dir ?? "south" }));
          const inv = block.getComponent("minecraft:inventory")?.container;
          if (!inv) continue;
          inv.clearAll();
          const n = 3 + Math.floor(Math.random() * 3);
          for (let i = 0; i < n; i++) {
            const loot = lootRoll();
            const slot = Math.floor(Math.random() * inv.size);
            if (loot.potion !== undefined) {
              dim.runCommand(`replaceitem block ${c.x} ${c.y} ${c.z} slot.container ${slot} ${loot.id.replace("minecraft:", "")} ${loot.count} ${loot.potion}`);
              continue;
            }
            const item = makeItem(loot);
            if (item) inv.setItem(slot, item);
          }
        } catch {}
      }
    });
  }
}

function startHunt(kind = "solo") {
  const queue = hunt.queues[kind];
  const ids = queue.filter((id) => byId(id) && st(byId(id)).mode === "lobby").slice(0, huntMax(kind));
  hunt.queues[kind] = [];
  hunt.cd[kind] = null;
  if (ids.length < 2) return;
  const maps = HUNTS.map((_, i) => i).filter((i) => S.hunt.maps[i] !== false && built(HUNTS[i].id));
  if (!maps.length) return;
  hunt.kind = kind;
  hunt.map = maps.includes(S.hunt.nextMap) ? S.hunt.nextMap : randOf(maps);
  const map = huntMap();
  // the hunted: 1, or 2 in "2 contra todos" (when there are at least 3 players)
  const nPreys = kind === "duo" && ids.length >= 3 ? 2 : 1;
  const pool = shuffle([...ids]);
  if (ids.includes(hunt.nextHunted)) pool.unshift(...pool.splice(pool.indexOf(hunt.nextHunted), 1));
  hunt.nextHunted = undefined;
  hunt.preys = pool.slice(0, nPreys);
  hunt.hunters = pool.slice(nPreys);
  hunt.alive = new Set(ids);
  hunt.spectators = new Set();
  hunt.names = Object.fromEntries(ids.map((id) => [id, byId(id).name]));
  hunt.timeLeft = S.hunt.timeLimit;
  hunt.headLeft = S.hunt.headStart;
  hunt.released = 0;
  hunt.finalDuel = false;
  hunt.lastStand = false;
  hunt.intro = true;
  hunt.phase = "running";
  if (S.hunt.chests) fillChests(map);

  const preyLoc = randomSpot(undefined, 0);
  const packLoc = randomSpot(preyLoc, 170);
  // the kit of the hunted gets better with the hunters each one has against them
  const kit = scaledHuntedKit(Math.max(1, Math.ceil(hunt.hunters.length / nPreys)));
  const team = nPreys > 1;
  hunt.preys.forEach((id, k) => {
    const prey = byId(id);
    const s = st(prey);
    s.mode = "hunt";
    s.role = "hunted";
    s.pad = null;
    s.lockAt = team ? { x: preyLoc.x + (k ? 1.5 : -1.5), y: preyLoc.y, z: preyLoc.z } : preyLoc;
    setMode(prey, GM.adventure);
    heal(prey);
    tp(prey, s.lockAt);
    giveKit(prey, kit);
    system.runTimeout(() => {
      try {
        if (valid(prey)) prey.getComponent("minecraft:health")?.resetToMaxValue();
      } catch {}
    }, 2);
    lockEffects(prey, 60);
    const mate = team ? ` Vas en equipo con §c${hunt.names[hunt.preys[1 - k]]}§r.` : "";
    prey.sendMessage(`§c[Caza]§r Eres el §ccazado§r en §6${map.name}§r (${KIND[kind].name}).${mate} Tu kit de hierro tiene §e+${kit.bonus}§r de mejora por los ${hunt.hunters.length} cazadores. Ventaja: §e${S.hunt.headStart} s§r. Las estructuras tienen escaleras y cofres con botín.`);
  });
  hunt.hunters.forEach((id, k) => {
    const p = byId(id);
    const hs = st(p);
    hs.mode = "hunt";
    hs.role = "hunter";
    hs.pad = null;
    setMode(p, GM.adventure);
    heal(p);
    const a = (k / hunt.hunters.length) * Math.PI * 2;
    hs.lockAt = { x: packLoc.x + Math.cos(a) * 2, y: packLoc.y, z: packLoc.z + Math.sin(a) * 2 };
    tp(p, hs.lockAt, preyLoc);
    giveKit(p, getKit("hunter"));
    lockEffects(p, 60);
    p.sendMessage(`§c[Caza]§r Eres §acazador§r en §6${map.name}§r. Atrapa a §c${preyNames()}§r antes de §e${fmtTime(S.hunt.timeLimit)}§r.`);
  });
  world.sendMessage(`§c[Caza · ${KIND[kind].name}]§r ¡Empieza la caza en §6${map.name}§r! §c${preyNames()}§r contra ${hunt.hunters.map((id) => `§a${hunt.names[id]}`).join("§r, ")}§r.`);
  huntMusicStart(S.hunt.music && HUNT_SONG >= 0 ? [HUNT_SONG] : []);
  const release = () => {
    hunt.intro = false;
    if (hunt.phase !== "running") return;
    for (const id of alivePreys()) {
      const p0 = byId(id);
      if (!p0) continue;
      unlock(p0);
      st(p0).lockAt = undefined;
      title(p0, "§c§l¡CORRE!", `§f${hunt.hunters.length} cazador(es) salen en §e${hunt.headLeft} s`, 40);
      sound(p0, "mob.wither.spawn", 0.5, 1.2);
    }
    for (const id of aliveHunters()) {
      const p = byId(id);
      if (!p) continue;
      if (hunt.headLeft > 0) effect(p, "blindness", hunt.headLeft + 1, 0);
      else unlock(p);
      title(p, "§a§lERES CAZADOR", `§fsales en §e${hunt.headLeft} s`, 40);
    }
    checkMusic();
  };
  if (S.hunt.cinematic) {
    cinematic(huntParticipants(), (p) => huntShots(map, p, isPrey(p.id), hunt.hunters.length, preyNames(), hunt.preys.filter((id) => id !== p.id).map((id) => hunt.names[id])[0])).then(release);
  } else release();
}

// Only one hunter left: the final duel. Whatever the time left, the hunt
// lasts 2:30 more from now (the hunt song goes on: it does not start again).
const FINAL_SECONDS = 150;
function checkMusic() {
  if (hunt.phase !== "running" || hunt.finalDuel || hunt.intro) return;
  if (!alivePreys().length || aliveHunters().length !== 1) return;
  hunt.finalDuel = true;
  hunt.timeLeft = FINAL_SECONDS;
  const preys = preyNames(alivePreys());
  for (const p of huntParticipants()) {
    title(p, "§4§l¡DUELO FINAL!", `§c${preys} §7contra §a${hunt.names[aliveHunters()[0]]} §7· §e${fmtTime(FINAL_SECONDS)}`, 50);
    sound(p, "mob.enderdragon.growl", 0.5, 1.1);
  }
  world.sendMessage(`§c[Caza]§r §4§lDuelo final:§r queda un cazador, §a${hunt.names[aliveHunters()[0]]}§r. Quedan §e${fmtTime(FINAL_SECONDS)}§r.`);
}

function forceLastStand(admin) {
  if (hunt.phase !== "running") return admin.sendMessage("§c[Admin] No hay ninguna caza en curso.");
  const secs = Math.max(1, S.hunt.lastStandMinutes) * 60;
  hunt.lastStand = true;
  hunt.timeLeft = Math.min(hunt.timeLeft, secs);
  const name = preyNames(alivePreys());
  for (const p of huntParticipants()) {
    title(p, "§4§lÚLTIMO EN PIE", `§flos cazadores tienen §e${fmtTime(hunt.timeLeft)}§f para atrapar a §c${name}`, 70);
    sound(p, "mob.enderdragon.growl", 0.6, 0.8);
  }
  world.sendMessage(`§c[Caza]§r §4§lÚltimo en pie:§r los cazadores tienen §e${fmtTime(hunt.timeLeft)}§r para atrapar a §c${name}§r. Si no, gana el cazado.`);
}

function huntEliminate(id, killerName, reason) {
  if (hunt.phase !== "running" || !hunt.alive.has(id)) return;
  hunt.alive.delete(id);
  const name = hunt.names[id];
  const prey = isPrey(id);
  for (const p of huntParticipants()) {
    p.sendMessage(`§c[Caza]§r ${prey ? "§c" : "§a"}${name}§r ${reason ?? (killerName ? `fue eliminado por §e${killerName}` : "fue eliminado")}§r.`);
  }
  if (prey && !alivePreys().length) {
    const all = hunt.preys.length > 1;
    return endHunt("hunters", killerName ? `${killerName} atrapó a ${all ? "los cazados" : name}` : `${name} cayó`);
  }
  if (!prey) addStat(name, "hl");
  const s = P.get(id);
  if (s) {
    s.mode = "hunt_spec";
    hunt.spectators.add(id);
  }
  if (prey) {
    for (const mate of alivePreys().map(byId).filter(Boolean)) title(mate, "§c§lESTÁS SOLO", `§fcayó §c${name}§f: sobrevive tú`, 40);
    return;
  }
  if (aliveHunters().length === 0) return endHunt("hunted", "todos los cazadores cayeron");
  checkMusic();
}

// Puts back the columns where players placed cobwebs, ladders or scaffolding.
function cleanPlaced() {
  if (!hunt.placed.size) return;
  const keys = new Set([...hunt.placed].map((k) => k.split(",").filter((_, i) => i !== 1).join(",")));
  const id = huntMap().id;
  hunt.placed.clear();
  world.setDynamicProperty("natura:huntPlaced", undefined);
  rebuildColumns(id, keys, "Limpiando la caza");
}

function savePlaced() {
  world.setDynamicProperty("natura:huntPlaced", JSON.stringify({ map: huntMap().id, keys: [...hunt.placed].slice(0, 2000) }));
}

function endHunt(winner, reason) {
  if (hunt.phase !== "running") return;
  hunt.phase = "ending";
  const names = preyNames();
  const team = hunt.preys.length > 1;
  const winners = winner === "hunted" ? hunt.preys : hunt.hunters;
  for (const id of winners) addStat(hunt.names[id], "hw");
  if (winner === "hunters") for (const id of hunt.preys) addStat(hunt.names[id], "hl");
  world.sendMessage(`§c[Caza]§r ${winner === "hunted" ? `§c${names}§r ${team ? "sobrevivieron" : "sobrevivió"} a la caza` : `Los cazadores atraparon a §c${names}§r`} §7(${reason})§r.`);
  // the victory cinematic: its hero is a hunted player still alive
  const hero = winner === "hunted" ? [...alivePreys(), ...hunt.preys].map(byId).find((p) => p && st(p).mode !== "lobby") : undefined;
  if (hero) {
    victoryCinematic(hero).catch((e) => console.warn(`[Natura PvP] victoria: ${e}`)).finally(finishHunt);
    return;
  }
  for (const p of huntParticipants()) {
    const won = winners.includes(p.id);
    title(p, winner === "hunted" ? (team ? "§c§lGANAN LOS CAZADOS" : "§c§lGANA EL CAZADO") : "§a§lGANAN LOS CAZADORES", `§f${reason}`, 70);
    if (won) sound(p, "random.levelup");
    unlock(p);
    effect(p, "resistance", 8, 255);
  }
  system.runTimeout(finishHunt, 6 * SEC);
}

function finishHunt() {
  huntMusicStop();
  const m = huntMap();
  for (const type of ["item", "arrow", "snowball", "ender_pearl", "fishing_hook", "wind_charge_projectile", "splash_potion"]) {
    cmd(`kill @e[type=${type},x=${m.x0},y=${HUNT.floor},z=${m.z0},dx=${HUNT.size},dy=${HUNT.clearTop - HUNT.floor},dz=${HUNT.size}]`);
  }
  for (const p of huntParticipants()) {
    const mode = st(p).mode;
    if (mode === "hunt" || mode === "hunt_spec" || mode === "victory") sendToLobby(p);
  }
  cleanPlaced();
  hunt.phase = "idle";
  hunt.preys = [];
  hunt.hunters = [];
  hunt.alive.clear();
  hunt.spectators.clear();
  hunt.finalDuel = false;
  hunt.lastStand = false;
}

// ------------------------------------------------------------ the victory of the hunted
// Everybody still in the hunt watches it (nobody can move): the hunted player
// walks into a safe room, looks at their hand, turns round and sees the door
// they came through close, looks down, thinking, and the camera goes up to the
// sun. With the "win" song. Then everybody goes back to the lobby.
function victoryDoor(open) {
  const { x, y, z } = VICTORY.door;
  const dim = overworld();
  for (const upper of [false, true]) {
    try {
      const states = { "minecraft:cardinal_direction": "north", door_hinge_bit: false, open_bit: open, upper_block_bit: upper };
      dim.getBlock({ x, y: y + (upper ? 1 : 0), z })?.setPermutation(mc.BlockPermutation.resolve("minecraft:wooden_door", states));
    } catch {}
  }
}

function sunPoint(from) {
  let t = 6000;
  try {
    t = world.getTimeOfDay();
  } catch {}
  const a = (t / 24000) * Math.PI * 2; // 0 sunrise (east), 6000 noon (up), 12000 sunset (west)
  return { x: from.x + Math.cos(a) * 40, y: from.y + Math.max(0.2, Math.sin(a)) * 40, z: from.z + 6 };
}

async function victoryCinematic(prey, viewers = huntParticipants().filter((p) => p.id !== prey.id && ["hunt", "hunt_spec", "spec"].includes(st(p).mode))) {
  const V = VICTORY;
  const all = [prey, ...viewers];
  const alive = () => all.filter(valid);
  if (isPrey(prey.id)) huntMusicStop(); // a test does not touch a real hunt
  else for (const p of all) stopSong(p);
  for (const p of all) {
    st(p).mode = "victory";
    lockInput(p, true);
    hud(p, false);
    camFade(p, 0.4, 1, 1);
  }
  await sleep(10);
  for (const p of viewers) {
    if (!valid(p)) continue;
    setMode(p, GM.spectator);
    tp(p, V.viewers);
  }
  clearPlayer(prey);
  heal(prey);
  effect(prey, "resistance", 30, 255);
  setMode(prey, GM.adventure);
  const north = (pt) => ({ x: pt.x, y: pt.y + 1.6, z: pt.z - 20 });
  tp(prey, V.start, north(V.start));
  await sleep(10);
  victoryDoor(true);
  const head = () => ({ x: prey.location.x, y: prey.location.y + 1.6, z: prey.location.z });
  const cams = (pos, look, ease) => {
    for (const p of alive()) camSet(p, pos, look, ease);
  };
  if (WIN_SONG >= 0) for (const p of alive()) playTrack(p, WIN_SONG);
  // 1. he walks along the path and into the room
  cams({ x: V.start.x + 4, y: V.start.y + 3.5, z: V.start.z + 4 }, head(), 0);
  cams({ x: V.door.x + 3.5, y: V.door.y + 2.8, z: V.door.z + 3 }, { x: V.door.x + 0.5, y: V.door.y + 1.4, z: V.door.z }, 4);
  const steps = 80;
  for (let i = 0; i <= steps && valid(prey); i++) {
    const z = V.start.z + (V.stop.z - V.start.z) * (i / steps);
    tp(prey, { x: V.stop.x, y: V.stop.y, z }, north({ x: V.stop.x, y: V.stop.y, z }));
    await sleep(1);
  }
  if (!valid(prey)) return victoryEnd(alive());
  // 2. he stops and looks at his hand
  const st0 = V.stop;
  cams({ x: st0.x - 0.4, y: st0.y + 1.9, z: st0.z - 2.8 }, { x: st0.x, y: st0.y + 1.5, z: st0.z }, 1);
  tp(prey, st0, { x: st0.x + 0.7, y: st0.y + 0.6, z: st0.z - 0.9 });
  await sleep(45);
  // 3. he turns round and sees the door close behind him
  cams({ x: st0.x - 1.3, y: st0.y + 2.2, z: st0.z - 2.2 }, { x: V.door.x + 0.5, y: V.door.y + 1, z: V.door.z + 0.5 }, 1);
  for (let i = 0; i <= 20 && valid(prey); i++) {
    const a = -Math.PI / 2 + (Math.PI * i) / 20; // from north to south
    tp(prey, st0, { x: st0.x + Math.cos(a) * 3, y: st0.y + 1.5, z: st0.z + Math.sin(a) * 3 });
    await sleep(1);
  }
  await sleep(10);
  victoryDoor(false);
  for (const p of alive()) sound(p, "random.door_close", 1, 0.9);
  await sleep(30);
  // 4. he looks down at the floor, thinking
  cams({ x: st0.x + 2.3, y: st0.y + 1.8, z: st0.z + 0.6 }, { x: st0.x, y: st0.y + 1.5, z: st0.z }, 1.2);
  if (valid(prey)) tp(prey, st0, { x: st0.x, y: st0.y - 3, z: st0.z + 0.8 });
  await sleep(50);
  // 5. the camera goes up through the skylight and looks at the sun
  const sky = { x: V.room.x + 0.5, y: V.floor + 14, z: V.room.z + 0.5 };
  cams(sky, sunPoint(sky), 2.4);
  title(prey, "§6§l¡VICTORIA!", "§fsobreviviste a la caza", 60);
  for (const p of viewers) {
    if (!valid(p)) continue;
    if (isPrey(p.id)) title(p, "§6§l¡VICTORIA!", `§fsobrevivisteis a la caza con §e${prey.name}`, 60);
    else title(p, hunt.preys.length > 1 ? "§c§lGANAN LOS CAZADOS" : "§c§lGANA EL CAZADO", `§f${prey.name} sobrevivió`, 60);
  }
  await sleep(52);
  return victoryEnd(alive());
}

async function victoryEnd(players) {
  for (const p of players) camFade(p, 0.6, 0.6, 1);
  await sleep(14);
  for (const p of players) {
    if (!valid(p)) continue;
    stopSong(p);
    camClear(p);
    hud(p, true);
    lockInput(p, false);
  }
  victoryDoor(true);
}

function queueTick() {
  let any = false;
  for (const kind of KINDS) {
    const q = (hunt.queues[kind] = hunt.queues[kind].filter((id) => byId(id) && st(byId(id)).mode === "lobby"));
    const n = q.length, min = huntMin(kind), max = huntMax(kind);
    const label = `§cCaza ${KIND[kind].short}`;
    if (!S.hunt.enabled || n < min) {
      hunt.cd[kind] = null;
      for (const id of q) bar(byId(id), `${label}: §fesperando jugadores §7(${n}/${max}, mínimo ${min})`);
      continue;
    }
    any = true;
    if (hunt.cd[kind] == null) hunt.cd[kind] = S.hunt.lobbyCountdown;
    if (n >= max) hunt.cd[kind] = Math.min(hunt.cd[kind], 5);
    for (const id of q) {
      const p = byId(id);
      bar(p, `${label}: §fempieza en §e${Math.max(0, hunt.cd[kind])}s §7(${n}/${max})`);
      if (hunt.cd[kind] <= 5) sound(p, "note.hat", 0.7, 1.4);
    }
  }
  hunt.phase = any ? "countdown" : "idle";
  // the first queue that gets to 0 starts; the other one waits for its turn
  let started = false;
  for (const kind of KINDS) {
    if (hunt.cd[kind] == null) continue;
    if (hunt.cd[kind]-- <= 0) {
      if (started) hunt.cd[kind] = 5;
      else {
        started = true;
        startHunt(kind);
      }
    }
  }
}

function huntTick() {
  if (hunt.phase === "idle" || hunt.phase === "countdown") return queueTick();
  for (const kind of KINDS) for (const id of hunt.queues[kind]) bar(byId(id), "§cCaza: §fhay una caza en curso, la tuya empieza cuando acabe");
  if (hunt.phase !== "running") return;
  // players that left
  for (const id of [...hunt.alive]) if (!byId(id)) huntEliminate(id, undefined, "abandonó la partida");
  if (hunt.phase !== "running" || hunt.intro) return;
  const preys = alivePreys().map(byId).filter(Boolean);
  if (hunt.headLeft > 0) {
    hunt.headLeft--;
    if (hunt.headLeft === 0) {
      for (const id of aliveHunters()) {
        const p = byId(id);
        unlock(p);
        title(p, "§a§l¡A CAZAR!", `§fencuentra a §c${preyNames(alivePreys())}`, 30);
        sound(p, "mob.wolf.howl", 1, 0.9);
        st(p).lockAt = undefined;
      }
      for (const prey of preys) {
        title(prey, "§c§l¡YA VIENEN!", "", 30);
        sound(prey, "mob.wolf.howl", 1, 0.9);
      }
    }
  } else hunt.released++;
  hunt.timeLeft--;
  const every = hunt.lastStand ? (S.hunt.reveal > 0 ? Math.min(S.hunt.reveal, 30) : 30) : S.hunt.reveal;
  if (every > 0 && hunt.released > 0 && hunt.released % every === 0 && preys.length) {
    for (const id of aliveHunters()) {
      const p = byId(id);
      for (const prey of preys) {
        const l = prey.location;
        p.sendMessage(`§c[Caza]§r §c${prey.name}§r fue visto en §eX ${Math.round(l.x)}  Y ${Math.round(l.y)}  Z ${Math.round(l.z)}`);
      }
      sound(p, "note.bell", 1, 1.2);
    }
    for (const prey of preys) {
      prey.sendMessage("§c[Caza]§r ¡Los cazadores han visto tu posición!");
      sound(prey, "note.bass", 1, 0.6);
    }
  }
  // the action bar: only the time left and a distance
  const hunters = aliveHunters().map(byId).filter(Boolean);
  const dist = (a, b) => Math.round(Math.sqrt(dist2(a.location, b.location)));
  const nearest = (p, list) => (list.length ? Math.min(...list.map((h) => dist(p, h))) : 0);
  const show = (d) => (d > 100 ? "+100" : `~${Math.max(5, Math.ceil(d / 5) * 5)}`);
  for (const p of huntParticipants()) {
    let d;
    if (isPrey(p.id) && hunt.alive.has(p.id)) d = nearest(p, hunters);
    else if (st(p).mode === "hunt") d = nearest(p, preys);
    else d = preys.length ? Math.min(...preys.map((q) => nearest(q, hunters))) : 0;
    bar(p, `§e${fmtTime(hunt.timeLeft)} §8· §f${show(d)} bloques`);
  }
  if (hunt.timeLeft <= 0) endHunt("hunted", hunt.preys.length > 1 ? "sobrevivieron hasta el final del tiempo" : "sobrevivió hasta el final del tiempo");
}

// ------------------------------------------------------------ Campal
const OBJ = "natura_campal";

function campalObjective() {
  return world.scoreboard.getObjective(OBJ) ?? world.scoreboard.addObjective(OBJ, "§a§lCampal §r§7· bajas");
}

function campalSidebar() {
  try {
    const slot = enumv(mc.DisplaySlotId, "Sidebar");
    if (S.campal.sidebar) world.scoreboard.setObjectiveAtDisplaySlot(slot, { objective: campalObjective(), sortOrder: enumv(mc.ObjectiveSortOrder, "Descending") });
    else world.scoreboard.clearObjectiveAtDisplaySlot(slot);
  } catch {}
}

function campalPlayers() {
  return world.getPlayers().filter((p) => st(p).mode === "campal");
}

function campalEnter(player) {
  if (!S.campal.enabled) return player.sendMessage("§c[Campal] La arena está cerrada por un administrador.");
  if (!built("campal")) return player.sendMessage("§e[Campal] La arena se está construyendo, espera un momento.");
  if (st(player).mode !== "lobby") return;
  leaveQueues(player);
  st(player).mode = "campal";
  spawnInCampal(player, true);
  modeMusic(player);
  world.sendMessage(`§a[Campal]§r §e${player.name}§r entró a la arena §7(${campalPlayers().length} dentro)`);
}

function spawnInCampal(player, first) {
  const others = campalPlayers().filter((p) => p.id !== player.id).map((p) => p.location);
  let best, bestD = -1;
  for (const sp of campalSpawns()) {
    const d = others.length ? Math.min(...others.map((o) => dist2(o, sp))) : Math.random();
    if (d > bestD) {
      best = sp;
      bestD = d;
    }
  }
  const s = st(player);
  s.pad = null;
  setMode(player, GM.adventure);
  heal(player);
  tp(player, best);
  giveKit(player, getKit("campal"));
  player.getComponent("minecraft:inventory")?.container?.setItem(8, ITEMS.leave());
  if (S.campal.spawnProtection > 0) effect(player, "resistance", S.campal.spawnProtection, 255);
  title(player, "§a§lCAMPAL", first ? "§fla arena siempre está activa" : "§f¡de vuelta a la pelea!", 30);
  try {
    const obj = campalObjective();
    if (!obj.hasParticipant(player)) obj.setScore(player, 0);
  } catch {}
}

function campalLeave(player) {
  if (inCombat(player)) {
    const left = Math.ceil((S.campal.combatTag * SEC - (system.currentTick - st(player).hurtTick)) / SEC);
    return player.sendMessage(`§c[Campal] Estás en combate. Espera ${left} s sin recibir daño para salir.`);
  }
  sendToLobby(player, "§a[Campal]§r Volviste al lobby.");
}

// ------------------------------------------------------------ deaths, damage, leaving
function killerOf(player, source) {
  let k = source?.damagingEntity;
  if (k?.typeId !== "minecraft:player") k = undefined;
  const s = st(player);
  if (!k && s.attacker && system.currentTick - s.attackerTick < 15 * SEC) k = byId(s.attacker);
  return k?.id !== player.id ? k : undefined;
}

world.afterEvents.entityDie.subscribe(({ deadEntity: player, damageSource }) => {
  if (player.typeId !== "minecraft:player") return;
  const s = st(player);
  const killer = killerOf(player, damageSource);
  addStat(player, "d");
  if (killer) addStat(killer, "k");
  s.attacker = undefined;
  if (s.mode === "duel" && s.match) {
    const m = s.match;
    const idx = m.ids.indexOf(player.id);
    s.mode = "lobby";
    endDuel(m, 1 - idx, m.phase !== "fight" ? "murió antes de empezar" : undefined);
  } else if (s.mode === "hunt") {
    huntEliminate(player.id, killer?.name);
  } else if (s.mode === "campal") {
    if (killer && st(killer).mode === "campal") {
      addStat(killer, "ck");
      try {
        campalObjective().addScore(killer, 1);
      } catch {}
      if (S.campal.reward) {
        effect(killer, "regeneration", 4, 2);
        const inv = killer.getComponent("minecraft:inventory")?.container;
        inv?.addItem(new ItemStack("minecraft:golden_apple", 2));
        inv?.addItem(new ItemStack("minecraft:ender_pearl", 1));
      }
      bar(killer, `§a+1 baja §7(eliminaste a §f${player.name}§7)`);
      sound(killer, "random.orb", 1, 1.6);
    }
    for (const p of campalPlayers()) if (p.id !== player.id) p.sendMessage(`§a[Campal]§r §c${player.name}§r ${killer ? `fue eliminado por §a${killer.name}` : "murió"}§r.`);
  }
}, { entityTypes: ["minecraft:player"] });

world.afterEvents.playerSpawn.subscribe(({ player, initialSpawn }) => {
  const s = st(player);
  if (initialSpawn) {
    P.delete(player.id);
    system.runTimeout(() => {
      if (!valid(player)) return;
      camClear(player);
      hud(player, true);
      if (!built("lobby")) {
        tp(player, { x: 0.5, y: LOBBY.y + 6, z: LOBBY.spawn.z });
        effect(player, "slow_falling", 30, 0);
        return;
      }
      secretFogOff(player); // in case they left the game inside the secret corridor
      sendToLobby(player, undefined, true);
      // The first song of a player who has just joined was not heard: the game
      // was still loading. It starts when they move, or after 5 seconds.
      st(player).joinMusic = { at: system.currentTick + 5 * SEC, from: { x: player.location.x, z: player.location.z } };
      if (opts(player).epic) epicView(player);
      title(player, "§2§lNATURA PvP", "§fbienvenido al Árbol del Mundo", 60);
      player.sendMessage("§2[Natura PvP]§r Usa la §abrújula§r (menú) o cruza una de las §6puertas de piedra§r: §bEmparejamiento§r, §cCaza§r o §aCampal§r. ");
      if (isAdmin(player)) player.sendMessage("§7Eres administrador: usa el §creloj§7 o §f/natura:admin§7 para abrir el panel.");
    }, 10);
    return;
  }
  // respawn after dying
  system.runTimeout(() => {
    if (!valid(player) || s.mode === "victory") return; // the victory cinematic takes care of it
    if (s.mode === "campal" && S.campal.enabled) spawnInCampal(player, false);
    else if (s.mode === "hunt_spec" && hunt.phase === "running") {
      clearPlayer(player);
      setMode(player, GM.spectator);
      tp(player, huntCenter());
      player.sendMessage("§c[Caza]§r Ahora eres espectador. Usa §e/natura:lobby§r para volver al lobby.");
      huntMusicJoin(player);
    } else if (s.mode !== "free") sendToLobby(player);
  }, 2);
});

world.afterEvents.entityHurt.subscribe(({ hurtEntity: player, damage, damageSource }) => {
  if (player.typeId !== "minecraft:player") return;
  const s = st(player);
  const attacker = damageSource?.damagingEntity;
  if (attacker?.typeId === "minecraft:player" && attacker.id !== player.id) {
    s.attacker = attacker.id;
    s.attackerTick = system.currentTick;
    s.hurtTick = system.currentTick;
    st(attacker).hurtTick = system.currentTick;
    // no friendly fire (among hunters, or between the two hunted): give the health back
    if (s.mode === "hunt" && st(attacker).mode === "hunt" && s.role === st(attacker).role && !S.hunt.friendlyFire) {
      try {
        const h = player.getComponent("minecraft:health");
        if (h.currentValue > 0) h.setCurrentValue(Math.min(h.effectiveMax, h.currentValue + damage));
      } catch {}
    }
  }
}, { entityTypes: ["minecraft:player"] });

world.afterEvents.playerLeave.subscribe(({ playerId }) => {
  const s = P.get(playerId);
  const a = duel.queue.indexOf(playerId);
  if (a >= 0) duel.queue.splice(a, 1);
  for (const k of KINDS) {
    const b = hunt.queues[k].indexOf(playerId);
    if (b >= 0) hunt.queues[k].splice(b, 1);
  }
  hunt.spectators.delete(playerId);
  if (s?.mode === "duel" && s.match) {
    const m = s.match;
    endDuel(m, 1 - m.ids.indexOf(playerId), "el rival abandonó");
  }
  if (s?.mode === "hunt") huntEliminate(playerId, undefined, "abandonó la partida");
  P.delete(playerId);
  personal.delete(playerId);
  playing.delete(playerId);
});

// ------------------------------------------------------------ blocks
// Nobody breaks the map. In the hunt, the cobwebs, ladders and scaffolding the
// players place can be removed (and are cleaned when the hunt ends).
world.beforeEvents.playerBreakBlock.subscribe((ev) => {
  const s = P.get(ev.player.id);
  if (s?.mode === "free") return;
  const { x, y, z } = ev.block.location;
  if (s?.mode === "hunt" && hunt.placed.has(`${x},${y},${z}`)) return;
  ev.cancel = true;
});

world.afterEvents.playerBreakBlock.subscribe(({ block }) => {
  const { x, y, z } = block.location;
  if (hunt.placed.has(`${x},${y},${z}`)) hunt.placed.add(`${x},${y},${z}`); // stays listed: the column is rebuilt anyway
});

world.afterEvents.playerPlaceBlock.subscribe(({ block, player }) => {
  const s = P.get(player.id);
  if (s?.mode === "free") return;
  const { x, y, z } = block.location;
  if (s?.mode === "hunt" && huntMap().inside(x, z) && PLACEABLE.has(block.typeId) && y < HUNT.clearTop) {
    hunt.placed.add(`${x},${y},${z}`);
    savePlaced();
    return;
  }
  try {
    block.setType("minecraft:air");
  } catch {}
});

// ------------------------------------------------------------ items
world.afterEvents.itemUse.subscribe(({ source: player, itemStack }) => {
  if (player?.typeId !== "minecraft:player") return;
  const kind = itemKind(itemStack);
  if (!kind) return;
  const s = st(player);
  if (system.currentTick - (s.lastUse ?? -99) < 8) return;
  s.lastUse = system.currentTick;
  if (kind === "selector") openSelector(player);
  else if (kind === "admin") openAdmin(player);
  else if (kind === "leave" && s.mode === "campal") campalLeave(player);
});

// ------------------------------------------------------------ lobby: pads, texts, safety
const PADS = Object.entries(LOBBY.pads);

function padUnder(player) {
  const l = player.location;
  if (l.y < LOBBY.y + 0.5 || l.y > LOBBY.y + 2.5) return null;
  for (const [k, pad] of PADS) if (Math.abs(Math.floor(l.x) - pad.x) <= 1 && Math.abs(Math.floor(l.z) - pad.z) <= 1) return k;
  return null;
}

function padAction(player, key) {
  if (key === "duel") duel.queue.includes(player.id) ? player.sendMessage("§b[Emparejamiento]§r Ya estás en la cola. Abre el menú para salir.") : duelJoin(player);
  else if (key === "hunt") queueOf(player.id) ? player.sendMessage("§c[Caza]§r Ya estás en la cola. Abre el menú para salir.") : huntChoice(player);
  else if (key === "campal") campalEnter(player);
}

const TEXTS = {
  welcome: { x: 0.5, y: LOBBY.y + 4.2, z: LOBBY.spawn.z - 4 },
  duel: { x: LOBBY.pads.duel.x + 0.5, y: LOBBY.y + 3.6, z: LOBBY.pads.duel.z + 0.5 },
  hunt: { x: LOBBY.pads.hunt.x + 0.5, y: LOBBY.y + 3.6, z: LOBBY.pads.hunt.z + 0.5 },
  campal: { x: LOBBY.pads.campal.x + 0.5, y: LOBBY.y + 3.6, z: LOBBY.pads.campal.z + 0.5 },
  betting: BETTING.sign,
};

function topLines(key) {
  const t = top(key);
  return t.length ? t.map(([n, s], i) => `§6${i + 1}. §f${n} §7(${s[key]})`).join("\n") : "§7sin partidas todavía";
}

function textFor(key) {
  if (key === "welcome") return "§2§lNATURA PvP\n§fel Árbol del Mundo\n§7usa la §abrújula§7 o cruza una puerta";
  if (key === "duel") {
    const busy = duel.matches.filter((m) => m).length;
    return `§b§lEMPAREJAMIENTO\n§71 contra 1 · ${DUELS.length} mapas\n§fen cola: §e${duel.queue.length} §7| §fduelos: §e${busy}\n${S.duel.enabled ? "" : "§c(desactivado)\n"}§6Top victorias\n${topLines("dw")}`;
  }
  if (key === "hunt") {
    const state = hunt.phase === "running" ? `§ccaza en curso §7(${KIND[hunt.kind].short}, ${huntMap().name})` : `§f1 vs todos: §e${hunt.queues.solo.length}/${huntMax("solo")} §7| §f2 vs todos: §e${hunt.queues.duo.length}/${huntMax("duo")}`;
    return `§c§lCAZA\n§71 contra todos · 2 contra todos · ${HUNTS.length} mapas\n${state}\n${S.hunt.enabled ? "" : "§c(desactivado)\n"}§6Top victorias\n${topLines("hw")}`;
  }
  if (key === "betting") return "§e§lSALA DE APUESTAS\n§7apuestas amigables entre jugadores\n§6(mantenimiento)";
  return `§a§lCAMPAL\n§7siempre abierta · entra cuando quieras\n§fdentro: §e${campalPlayers().length}\n${S.campal.enabled ? "" : "§c(cerrado)\n"}§6Top bajas\n${topLines("ck")}`;
}

function updateTexts() {
  const dim = overworld();
  try {
    if (!dim.getBlock({ x: 0, y: LOBBY.y, z: 0 })) return;
  } catch {
    return;
  }
  let all = [];
  try {
    all = dim.getEntities({ type: "natura:text" });
  } catch {
    return;
  }
  for (const [key, loc] of Object.entries(TEXTS)) {
    const tag = `natura_text_${key}`;
    const mine = all.filter((e) => e.hasTag(tag));
    let e = mine.shift();
    for (const extra of mine) extra.remove();
    if (!e) {
      try {
        e = dim.spawnEntity("natura:text", loc);
        e.addTag(tag);
      } catch {
        continue;
      }
    }
    const text = textFor(key);
    if (e.nameTag !== text) e.nameTag = text;
    if (dist2(e.location, loc) > 0.1 || Math.abs(e.location.y - loc.y) > 0.1) e.teleport(loc);
  }
}

// ------------------------------------------------------------ the secret corridor
// A dark pit in a forgotten corner of the lobby. Who falls in appears in a
// colossal corridor far away, in a thicker fog, for 10 seconds; then back to
// the lobby, and the fog (and everything else) goes away.
const SECRET = LOBBY.secret;
const SECRET_FOG = "natura_corridor";
function inSecret(l) {
  const x = Math.floor(l.x), z = Math.floor(l.z);
  return x >= SECRET.x0 && x <= SECRET.x1 && z >= SECRET.z0 && z <= SECRET.z1 && l.y < SECRET.y - 0.3 && l.y > SECRET.y - 8;
}

function secretFogOff(player) {
  st(player).fog = false;
  pcmd(player, `fog @s remove ${SECRET_FOG}`);
}

function secretEnter(player) {
  const s = st(player);
  leaveQueues(player);
  s.mode = "secret";
  s.secretEnd = system.currentTick + CORRIDOR.seconds * SEC + 10;
  stopMusic(player);
  camFade(player, 0.2, 0.4, 1.6);
  effect(player, "resistance", CORRIDOR.seconds + 4, 255);
  system.runTimeout(() => {
    if (!valid(player) || st(player).mode !== "secret") return;
    tp(player, CORRIDOR.spawn, CORRIDOR.look);
    pcmd(player, `fog @s push natura:corridor ${SECRET_FOG}`);
    s.fog = true;
    sound(player, "ambient.cave", 1, 0.7);
    sound(player, "mob.warden.nearby_closest", 0.4, 0.6);
  }, 8);
}

function secretTick(player, s) {
  const l = player.location;
  if (system.currentTick >= s.secretEnd) {
    s.secretEnd = Infinity;
    camFade(player, 0.6, 0.4, 1.2);
    system.runTimeout(() => {
      if (!valid(player) || st(player).mode !== "secret") return;
      clearEffects(player);
      sendToLobby(player);
    }, 14);
    return;
  }
  // nobody gets lost in it (nor reaches its end)
  if (s.fog && (l.y < CORRIDOR.floor - 2 || Math.abs(l.x - CORRIDOR.spawn.x) > 20 || l.z > CORRIDOR.spawn.z + 4 || l.z < CORRIDOR.spawn.z - CORRIDOR.length + 40)) tp(player, CORRIDOR.spawn, CORRIDOR.look);
}

// ------------------------------------------------------------ the boss hunt (coming soon)
function bossSoon(player) {
  title(player, "§5§lCAZA DEL JEFE", "§dpróximamente", 50);
  sound(player, "mob.wither.ambient", 0.4, 0.8);
  player.sendMessage("§5[Caza del jefe]§r Jugadores contra mobs: un jefe enorme y sus esbirros contra todos vosotros. §dTodavía no está disponible, ¡pero llegará pronto!");
}

// ------------------------------------------------------------ the main loop
let tick = 0;
system.runInterval(() => {
  tick++;
  const slow = tick % 8 === 0;
  for (const player of world.getPlayers()) {
    const s = st(player);
    const l = player.location;
    if (s.mode === "lobby") {
      if (!built("lobby")) {
        if (l.y < LOBBY.y - 4) tp(player, { x: 0.5, y: LOBBY.y + 6, z: LOBBY.spawn.z });
        effect(player, "slow_falling", 5, 0);
        continue;
      }
      if (s.joinMusic && (system.currentTick >= s.joinMusic.at || dist2(l, s.joinMusic.from) >= 1)) {
        s.joinMusic = null;
        lobbyMusic(player);
      }
      if (s.intro) {
        epicTick(player, s);
        continue;
      }
      if (inSecret(l)) {
        secretEnter(player);
        continue;
      }
      if (l.y < LOBBY.y - 20 || Math.hypot(l.x, l.z) > LOBBY.radius + 6) tp(player, LOBBY.spawn, LOBBY.look);
      if (slow) {
        effect(player, "resistance", 12, 255);
        effect(player, "saturation", 12, 255);
        setMode(player, GM.adventure);
        const inv = player.getComponent("minecraft:inventory")?.container;
        if (inv) {
          if (itemKind(inv.getItem(0)) !== "selector") inv.setItem(0, ITEMS.selector());
          const has = itemKind(inv.getItem(8)) === "admin";
          if (isAdmin(player) && !has) inv.setItem(8, ITEMS.admin());
          if (!isAdmin(player) && has) inv.setItem(8, undefined);
        }
      }
      const pad = padUnder(player);
      if (pad && pad !== s.pad) padAction(player, pad);
      s.pad = pad;
    } else if (s.mode === "duel" && s.match) {
      const sp = s.match.spawns[s.match.ids.indexOf(player.id)];
      if ((s.match.phase === "countdown" || s.match.phase === "intro") && dist2(l, sp) > 0.5) tp(player, sp);
      else if (l.y < DUEL.y - 3 || !insideArea(DUELS[s.match.i].id, l.x, l.z)) tp(player, sp);
    } else if (s.mode === "hunt") {
      const m = huntMap();
      if (s.lockAt && (hunt.intro || hunt.headLeft > 0) && dist2(l, s.lockAt) > 1) tp(player, s.lockAt);
      if (!m.inside(Math.floor(l.x), Math.floor(l.z)) || l.y < HUNT.floor) {
        const x = Math.max(m.x0 + 3, Math.min(m.x1 - 3, Math.floor(l.x)));
        const z = Math.max(m.z0 + 3, Math.min(m.z1 - 3, Math.floor(l.z)));
        tp(player, { x: x + 0.5, y: m.surface(x, z).y + 1, z: z + 0.5 });
      }
    } else if (s.mode === "secret") {
      secretTick(player, s);
    } else if (s.mode === "hunt_spec" || s.mode === "spec") {
      specTick(player, s);
    } else if (s.mode === "campal") {
      if (l.y < CAMPAL.y - 4 || !insideArea("campal", l.x, l.z)) spawnInCampal(player, false);
    } else if (s.mode === "free" && slow && isAdmin(player)) {
      const inv = player.getComponent("minecraft:inventory")?.container;
      if (inv && ![...Array(inv.size).keys()].some((i) => itemKind(inv.getItem(i)) === "admin")) inv.setItem(8, ITEMS.admin());
    }
  }
}, 5);

system.runInterval(() => {
  try {
    duelTick();
  } catch (e) {
    console.warn(`[Natura PvP] duelo: ${e}`);
  }
  try {
    huntTick();
  } catch (e) {
    console.warn(`[Natura PvP] caza: ${e}`);
  }
  if (progress.busy && progress.total > 2000) {
    const text = `§7Construyendo el mapa: §f${progress.label} §e${pct()}%`;
    for (const p of world.getPlayers()) if (isAdmin(p) || !built("lobby") || st(p).mode === "lobby") bar(p, text);
  }
}, SEC);

system.runInterval(updateTexts, 2 * SEC);

function pct() {
  return progress.total ? Math.floor((progress.done / progress.total) * 100) : 0;
}

// ------------------------------------------------------------ the map: prebuilt or built by the script
// The .mcworld comes with the whole map already built. If the packs are used in
// another world (or in a world from an older version), the script builds it.
async function ensureBuilt() {
  const ids = AREAS.map((a) => a.id);
  const marks = ids.map((id) => world.getDynamicProperty(`natura:built:${id}`));
  const fresh = marks.every((v) => v === undefined) && world.getDynamicProperty("natura:built:hunt") === undefined;
  if (fresh) {
    const id = await probe(LOBBY.marker.x, LOBBY.marker.y, LOBBY.marker.z);
    if (id && id !== "minecraft:air") {
      for (const a of ids) world.setDynamicProperty(`natura:built:${a}`, CFG.buildVersion);
      world.setDynamicProperty("natura:prebuilt", CFG.buildVersion);
      for (const p of world.getPlayers()) if (st(p).mode === "lobby") sendToLobby(p);
      return afterBuilt();
    }
  }
  const old = !fresh; // a world from an older version: rebuild over what is there
  for (const id of ids) {
    if (built(id)) continue;
    const ok = (await buildArea(id, old)) === true;
    if (ok) world.setDynamicProperty(`natura:built:${id}`, CFG.buildVersion);
    if (id === "lobby" && ok) {
      for (const p of world.getPlayers()) {
        if (st(p).mode !== "lobby") continue;
        sendToLobby(p);
        title(p, "§2§lNATURA PvP", "§fel mapa se está terminando de construir", 60);
      }
    }
    if (ok) world.sendMessage(`§2[Natura PvP]§r ${AREA[id].name}: lista.`);
  }
  afterBuilt();
}

function afterBuilt() {
  // cobwebs and ladders left by a hunt that was cut short (the world closed)
  try {
    const left = JSON.parse(world.getDynamicProperty("natura:huntPlaced") ?? "null");
    if (left?.keys?.length && AREA[left.map]) {
      const keys = new Set(left.keys.map((k) => k.split(",").filter((_, i) => i !== 1).join(",")));
      rebuildColumns(left.map, keys, "Limpiando la caza");
    }
    world.setDynamicProperty("natura:huntPlaced", undefined);
  } catch {}
}

async function rebuild(id) {
  world.setDynamicProperty(`natura:built:${id}`, "rebuilding");
  const ok = (await buildArea(id, true)) === true;
  world.setDynamicProperty(`natura:built:${id}`, CFG.buildVersion);
  world.sendMessage(`§2[Natura PvP]§r ${AREA[id].name}: reconstruida${ok ? "" : " (con errores)"}.`);
}

world.afterEvents.worldLoad.subscribe(() => {
  loadSettings();
  loadStats();
  applyGamerules();
  campalSidebar();
  ensureBuilt();
});

// ------------------------------------------------------------ menus
// buttons: [text, action, icon]. With `back`, a last button returns there.
async function menu(player, titleText, body, buttons, back) {
  const form = new ui.ActionFormData().title(titleText).body(body);
  const list = back ? [...buttons, ["§8« Volver", back, "textures/ui/arrow_left"]] : buttons;
  for (const [text, , icon] of list) form.button(text, icon);
  const r = await showForm(player, form);
  if (!r || r.canceled || !list[r.selection]) return;
  await list[r.selection][1]();
}

async function confirm(player, titleText, body) {
  const form = new ui.MessageFormData().title(titleText).body(body).button1("§a§lSí").button2("§cNo");
  const r = await showForm(player, form);
  return r && !r.canceled && r.selection === 0;
}

// ------------------------------------------------------------ the player menu
async function openSelector(player) {
  const s = st(player);
  if (s.mode === "campal") return campalLeave(player);
  if (s.mode !== "lobby") return;
  const inDuel = duel.queue.includes(player.id), inHuntQ = !!queueOf(player.id);
  const queueText = inDuel ? "§bEstás en la cola de Emparejamiento." : inHuntQ ? "§cEstás en la cola de la Caza." : "§7No estás en ninguna cola.";
  const huntState = `1 vs todos: ${hunt.queues.solo.length} · 2 vs todos: ${hunt.queues.duo.length}`;
  const buttons = [
    [inDuel ? "§c§lSALIR DE LA COLA\n§r§8Emparejamiento" : `§b§lEMPAREJAMIENTO\n§r§81 contra 1 · ${duel.queue.length} en cola`, () => (inDuel ? duelLeave(player) : duelJoin(player)), "textures/items/diamond_sword"],
    hunt.phase === "running"
      ? [`§c§lCAZA §r§8(en curso en ${huntMap().name})\n§8mirar como espectador`, () => huntSpectate(player), "textures/items/bow_standby"]
      : [inHuntQ ? "§c§lSALIR DE LA COLA\n§r§8Caza" : `§c§lCAZA\n§r§8${huntState}`, () => huntChoice(player), "textures/items/bow_standby"],
    [`§a§lCAMPAL\n§r§8${campalPlayers().length} dentro · entra ya`, () => campalEnter(player), "textures/items/iron_sword"],
    [`§7§lESPECTAR\n§r§8${specTargets().length} partida(s) en curso`, () => specMenu(player), "textures/items/spyglass"],
    ["§5§lCAZA DEL JEFE\n§r§8jugadores contra mobs · §dpróximamente", () => bossSoon(player), "textures/items/nether_star"],
    ["§e§lSALA DE APUESTAS\n§r§8en mantenimiento", () => player.sendMessage("§e[Apuestas]§r La sala de apuestas está en mantenimiento. ¡Pronto!"), "textures/items/gold_ingot"],
    ["§e§lESTADÍSTICAS\n§r§8las tuyas y el ranking", () => openStats(player), "textures/items/book_normal"],
    ["§3§lOPCIONES\n§r§8música, volumen y vista épica", () => openOptions(player), "textures/ui/settings_glyph_color_2x"],
  ];
  if (isAdmin(player)) buttons.push(["§4§lADMINISTRACIÓN\n§r§8panel de administrador", () => openAdmin(player), "textures/items/clock_item"]);
  await menu(player, "§l§2NATURA PvP", `§fHola, §e${player.name}§f. ¿A qué quieres jugar?\n${queueText}\n `, buttons);
}

async function openStats(player, name = player.name) {
  const s = STATS[name] ?? {};
  const lines = Object.entries(STAT_NAMES).map(([k, label]) => `§7${label}: §f${s[k] ?? 0}`);
  const kd = (s.k ?? 0) / Math.max(1, s.d ?? 0);
  const rank = ["k", "dw", "hw", "ck"].map((k) => `§6${STAT_NAMES[k]}\n${topLines(k)}`).join("\n");
  await menu(player, `§l${name}`, `${lines.join("\n")}\n§7K/D: §f${kd.toFixed(2)}\n\n§l§eRANKING§r\n${rank}\n `, [["§8Cerrar", () => {}]]);
}

// ------------------------------------------------------------ the admin panel
// fields: [key, type, label, ...]: toggle | slider(min, max, step) | dropdown(options)
async function settingsForm(player, section, titleText, fields) {
  const form = new ui.ModalFormData().title(titleText);
  for (const [key, type, label, a, b, c] of fields) {
    const v = S[section][key];
    if (type === "toggle") form.toggle(label, { defaultValue: !!v });
    else if (type === "slider") form.slider(label, a, b, { valueStep: c, defaultValue: Math.max(a, Math.min(b, v)) });
    else if (type === "dropdown") form.dropdown(label, a, { defaultValueIndex: v });
  }
  form.submitButton("§a§lGuardar");
  const r = await showForm(player, form);
  if (!r || r.canceled || !r.formValues) return false;
  fields.forEach(([key], i) => {
    if (r.formValues[i] !== undefined) S[section][key] = r.formValues[i];
  });
  saveSettings();
  player.sendMessage("§a[Admin] Ajustes guardados.");
  return true;
}

// Which maps of a mode can come out, and which one comes next.
async function mapsForm(player, section, maps) {
  const form = new ui.ModalFormData().title(section === "duel" ? "Mapas de Emparejamiento" : "Mapas de la Caza");
  maps.forEach((m, i) => form.toggle(`§f${m.name} §7— ${m.desc}`, { defaultValue: S[section].maps[i] !== false }));
  form.dropdown("§eSiguiente mapa", ["Al azar (entre los activados)", ...maps.map((m) => m.name)], { defaultValueIndex: S[section].nextMap + 1 });
  form.submitButton("§a§lGuardar");
  const r = await showForm(player, form);
  if (!r || r.canceled || !r.formValues) return;
  const v = r.formValues;
  S[section].maps = maps.map((_, i) => !!v[i]);
  if (!S[section].maps.some((x) => x)) {
    S[section].maps[0] = true;
    player.sendMessage("§e[Admin] Al menos un mapa tiene que estar activado: se deja el primero.");
  }
  S[section].nextMap = v[maps.length] - 1;
  saveSettings();
  player.sendMessage(`§a[Admin] Mapas guardados. Siguiente: §f${S[section].nextMap >= 0 ? maps[S[section].nextMap].name : "al azar"}`);
}

function requireAdmin(player) {
  if (isAdmin(player)) return true;
  player.sendMessage(`§c[Natura PvP] Necesitas la etiqueta "${ADMIN_TAG}" (/tag @s add ${ADMIN_TAG}).`);
  return false;
}

